# Test function R(y) = (y+1)^3 - 7(y+1) + 7, corresponding to c=1
def R_c1(y):
    return (y+1)**3 - 7*(y+1) + 7

# Check small integers y
test_y = [-5, -4, -3, -2, -1, 0, 1, 2, 3, 4]
results = {}
for y in test_y:
    val = R_c1(y)
    is_square = int(val**0.5)**2 == val
    results[y] = {"value": val, "is_square": is_square}

print("--- Test results for R(y) = (y+1)^3 - 7(y+1) + 7 ---")
for y, res in results.items():
    print(f"y={y}: Value={res['value']}, Is Square={res['is_square']}")

